system.ontology:
[Ontology]
step
  LABELED — A name and, optionally, a description. Example: { name: "Motor arm" }
    name: string — A name for eyes. Example: "Bolt, short"
    description?: string — One line more. Example: "M3x16"
  ASSEMBLED — What a step does to the build — the placements it names, by slug; the fold reads them in guide order. Example: { placements: [{ literal: "drone_rig.arm.0", active: true }] }
    placements: object[] — The placements this step installs or removes, by slug. Example: [{ literal: "drone_rig.arm.0", active: true }]
  INSTRUCTED — What a step (or a guide's intro) tells the builder — numbered lines and media. Example: { lines: [{ text: "Thread the 16mm bolt." }], images: [] }
    lines: object[] — The numbered body, one sentence per line. Example: [{ text: "Place one arm on top." }]
    images: string[] — File paths. Example: ["manual/cf5a470bc835.webp"]
  ANNOTATED — The callouts of a step or a guide. Example: { notes: [{ text: "Leave it loose.", symbols: ["note.warning", "warn.loose"] }] }
    notes: object[] — Callouts beside the body. Example: [{ text: "Leave it loose.", symbols: ["note.warning"] }]
  STAGED — How the stage shows a step or a guide's overview. Example: { camera: { target: [0, 0, 0], position: [0.3, 0.25, 0.3] }, explode: 0 }
    camera?: object — The stage's camera for this step. Example: { target: [0, 0, 0], position: [0.3, 0.25, 0.3] }
    explode?: number — How far the parts fly apart, 0 to 1. Example: 0.4
    ghost?: boolean — true draws what is not built yet as a ghost. Example: true
    built?: object — What the stage shows as already built; absent, every earlier step. Example: { steps: ["drone.01"], placements: [] }
    tints?: object — Placement slug → a theme role. Example: { "drone_rig.arm.0": "warning" }

guide
  LABELED — A name and, optionally, a description. Example: { name: "Motor arm" }
    name: string — A name for eyes. Example: "Bolt, short"
    description?: string — One line more. Example: "M3x16"
  SEQUENCED — A guide's subject and its steps in sections. Example: { subject: "drone_rig", sections: [{ name: "Frame", steps: ["drone.01", "drone.02"] }] }
    subject?: string — The part this guide builds — what the stage draws. Example: "drone_rig"
    sections: object[] — The sections in order; the step order is their steps flattened. Example: [{ name: "Frame", steps: ["drone.01"] }]
